INSERT INTO issues (id, slug, title, settlement, address, category, type, status, supporters_count, supporters_change_24h, summary, problem, request, lat, lng, images, organization_id, article_slug, created_at) VALUES
  ('iss-001', 'zebra-kell-az-iskola-ele', 'Zebra kell az iskola elé', 'Budaörs', 'Szabadság út', 'kozlekedes', 'problema', 'vizsgalat', 824, 312, 'A gyalogosok nehezen tudnak biztonságosan átkelni az iskola előtt.', 'A 1. számú általános iskola előtt reggelente és délutánonként több száz gyerek és szülő kel át az úton. Nincs kijelölt gyalogátkelőhely, a forgalom gyors, és több közel-baleset is történt az elmúlt hónapokban. A meglévő zebra több mint 200 méterre van.', 'Gyalogátkelőhely kialakítását és 30 km/h-s sebességkorlátozást az iskola előtti szakaszon.', 47.4608, 18.9583, ARRAY['https://images.unsplash.com/photo-1544620341-1adc273c8312?w=1200&q=80','https://images.unsplash.com/photo-1449824913935-59a10b8d2000?w=800&q=80']::text[], 'org-budaors', 'tobb-szazan-kernek-zebrat-az-iskola-ele-budaorson', '2026-09-24T08:12:00+02:00'::timestamptz),
  ('iss-002', 'katyus-utszakasz-az-m1-felhajtonal', 'Kátyús útszakasz az M1 felhajtónál', 'Budapest', 'XI. kerület, Budaörsi út', 'katyu', 'problema', 'folyamatban', 1456, 89, 'Több méteres kátyúk veszélyeztetik a felhajtó forgalmát.', 'Az M1 felhajtó előtt több mély kátyú alakult ki. Eső után víz áll bennük, sötétben nehezen láthatók. Több gumiabroncs-sérülésről is beszámoltak a helyi sofőrök.', 'Az útszakasz mielőbbi javítását és burkolatcsere ütemezését.', 47.4682, 19.0251, ARRAY['https://images.unsplash.com/photo-1515162816999-a0c47dc192f7?w=1200&q=80']::text[], 'org-kozut', NULL, '2026-09-10T14:30:00+02:00'::timestamptz),
  ('iss-003', 'vilagitas-hianyzik-a-jatszoteron', 'Világítás hiányzik a játszótéren', 'Érd', 'Park utca 12.', 'vilagitas', 'problema', 'ertesitve', 412, 54, 'Sötétedés után a játszótér használhatatlan a hiányzó lámpák miatt.', 'A parkban három lámpatest évek óta nem működik. Este a szülők nem merik a gyerekeket a játszótérre vinni, a környék pedig balesetveszélyes.', 'A lámpatestek javítását vagy cseréjét 30 napon belül.', 47.3912, 18.9135, '{}', 'org-erd', NULL, '2026-09-18T19:05:00+02:00'::timestamptz),
  ('iss-004', 'illegális-hulladeklerako-a-patak-menten', 'Illegális hulladéklerakó a patak mentén', 'Törökbálint', 'Patakparti sétány', 'koztisztasag', 'problema', 'vizsgalat', 678, 121, 'Építési törmelék és háztartási hulladék gyűlik a patakparton.', 'Az elmúlt hetekben rendszeresen hordanak építési törmeléket és zsákos hulladékot a patakparti sétány mellé. A bűz erősödik, és félek, hogy a következő esőnél a patakba kerül.', 'Hulladékelszállítást, kamerás megfigyelést és rendszeres ellenőrzést.', 47.4331, 18.9142, ARRAY['https://images.unsplash.com/photo-1532996122724-e3c354a0b4da?w=1200&q=80']::text[], 'org-torokbalint', NULL, '2026-09-20T11:20:00+02:00'::timestamptz),
  ('iss-005', 'uj-padok-a-vasutallomasnal', 'Új padok a vasútállomásnál', 'Budaörs', 'Vasút utca', 'egyeb', 'javaslat', 'uj', 298, 76, 'Az időseknek és ingázóknak nincs hol várakozniuk fedetten.', 'A vasútállomás peronján csak két pad van, és azok is rossz állapotban. Esőben és kánikulában különösen nehéz a várakozás az idősebbeknek.', 'Legalább négy új, fedett váróhellyel ellátott pad telepítését.', 47.4589, 18.9512, '{}', NULL, NULL, '2026-09-22T07:45:00+02:00'::timestamptz),
  ('iss-006', 'fák-pótlása-a-főtéren', 'Fák pótlása a főtéren', 'Budakeszi', 'Fő tér', 'zoldterulet', 'javaslat', 'folyamatban', 931, 44, 'A kivágott fák helyére új ültetést kérnek a lakók.', 'Tavasszal öt idős fát vágtak ki a főtéren. Az árnyék eltűnt, a tér nyáron tűző napos lett. Az ígért pótlás még nem történt meg.', 'Legalább öt őshonos fa ültetését az őszi ültetési időszakban.', 47.5142, 18.9281, ARRAY['https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=1200&q=80']::text[], 'org-budakeszi', NULL, '2026-08-28T16:00:00+02:00'::timestamptz),
  ('iss-007', 'uj-zebra-keszult-az-iskola-ele', 'Új zebra készült az iskola elé', 'Solymár', 'Iskola utca', 'kozlekedes', 'problema', 'megoldott', 1842, 0, 'A közösségi bejelentés után 23 nap alatt megépült a gyalogátkelőhely.', 'Az iskola előtt nem volt biztonságos átkelési lehetőség. A szülők hónapok óta kérték a zebrát.', 'Gyalogátkelőhely kialakítását az iskola főbejárata előtt.', 47.5921, 18.9284, ARRAY['https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?w=1200&q=80']::text[], 'org-solymar', NULL, '2026-08-01T09:00:00+02:00'::timestamptz),
  ('iss-008', 'megjavitottak-a-jatszoteri-lampakat', 'Megjavították a játszótéri lámpákat', 'Budapest', 'II. kerület, Fillér utca', 'vilagitas', 'problema', 'megoldott', 623, 0, 'Három hónap után újra világít a játszótér.', 'Több lámpa nem működött a játszótéren este.', 'A világítás helyreállítását.', 47.5152, 19.0123, '{}', NULL, NULL, '2026-07-15T10:00:00+02:00'::timestamptz),
  ('iss-009', 'parkolohelyek-az-orvosi-rendelo-elott', 'Parkolóhelyek az orvosi rendelő előtt', 'Budaörs', 'Egészségház utca', 'parkolas', 'javaslat', 'vizsgalat', 367, 28, 'Mozgáskorlátozott várakozási helyek hiányoznak a rendelő előtt.', 'Az orvosi rendelő előtt nincs kijelölt mozgáskorlátozott parkoló. Az időseknek gyakran messzebbről kell gyalogolniuk.', 'Legalább két kijelölt akadálymentes parkolóhelyet.', 47.4621, 18.9601, '{}', NULL, NULL, '2026-09-15T12:00:00+02:00'::timestamptz)
INSERT INTO official_responses (id, issue_id, organization_name, summary, original_text, verified, responded_at) VALUES
  ('resp-001', 'iss-001', 'Budaörs Város Önkormányzata', 'Az önkormányzat helyszíni vizsgálatot kezdeményezett, és október 15-ig dönt a további lépésekről.', 'Tisztelt Érintettek!
